function OnShowQuest()

 --Quest List Informations
	LoadValue()

	NumberData.IsSystemQuest = 1
	StringData.QuestName = "EP8.황제는..."

	NumberData.QuestBtn_Visible = 1
	StringData.QuestBtn_Path = "Quest/Event_2008_07_22_List.bmp"

	NumberData.DoneBtn_Count = 1
	NumberData.DoneBtn00_Visible = CheckDoneButtonVisible()
	StringData.DoneBtn00_Path = "Quest/Event_2008_07_22_Bt.bmp"
	NumberData.DoneBtn00_PosX = 101
	NumberData.DoneBtn00_PosY = 298

    NumberData.Msg_Count = 1
    NumberData.Msg00_Style = 0
	NumberData.Msg00_TextColor = 3276805
	NumberData.Msg00_OutlineColor = 0

    NumberData.Back_Visible = 1

    --  Navitigation buttons
    NumberData.NaviBtn_Count = 2

	NumberData.NaviBtn00_Visible = 1
	StringData.NaviBtn00_Path = "Quest/Event_2008_07_22_Back_BtLeft.bmp"
	NumberData.NaviBtn00_PosX = 316
	NumberData.NaviBtn00_PosY = 254

    NumberData.NaviBtn01_Visible = 0
	StringData.NaviBtn01_Path = "Quest/Event_2008_07_22_Back_BtRight.bmp"
	NumberData.NaviBtn01_PosX = 316 + 19
	NumberData.NaviBtn01_PosY = 254

 	--Page Info
		StringData.Back_Path = BackPath[IsDone()]

		StringData.AniImg00_Path = AniPath[IsDone()]
       	NumberData.AniImg_Count = 1
		NumberData.AniImg00_Frame = 0
		NumberData.AniImg00_PosX = AniPosX[IsDone()]
		NumberData.AniImg00_PosY = AniPosY[IsDone()]
		NumberData.AniImg00_Total = 2
		NumberData.AniImg00_Delay = AniDelay[IsDone()]

        StringData.Msg00_Content = StringData[IsDone() + Rewarded()]
        NumberData.Msg00_PosX = StringPosX[IsDone() + Rewarded()]
        NumberData.Msg00_PosY = StringPosY[IsDone() + Rewarded()]
        -- StringData.Msg00_Content = NumberData.Log1 .. " " .. NumberData.Log2 .. " " .. NumberData.Log3 .. " " .. NumberData.Log4 .. " " .. NumberData.Log5 .. " " .. NumberData.Log6
        -- NumberData.Msg00_PosX = 112
        -- NumberData.Msg00_PosY = 286


	if IsDone() == 1 then
		LoadValue()
   		NumberData.NaviBtn00_Visible = 0
		NumberData.NaviBtn01_Visible = 0

		NumberData.Img_Count = 14

		StringData.Img00_Path = ImgPath.Up1
		NumberData.Img00_Frame = 0
		NumberData.Img00_PosX = 40
		NumberData.Img00_PosY = 275

	    -- Monster counter

	    StringData.Img01_Path = CounterPath
	    NumberData.Img01_Frame = GetNumInPos(NumberData.Log1, 10)
	    NumberData.Img01_PosX = 75
	    NumberData.Img01_PosY = 341

	    StringData.Img02_Path = CounterPath
	    NumberData.Img02_Frame = GetNumInPos(NumberData.Log1, 1)
	    NumberData.Img02_PosX = NumberData.Img01_PosX + 20
	    NumberData.Img02_PosY = 341

		--MonPen counter
	    StringData.Img03_Path = CounterPath
	    NumberData.Img03_Frame = GetNumInPos(NumberData.Log4, 10)
	    NumberData.Img03_PosX = 166
	    NumberData.Img03_PosY = 341

	    StringData.Img04_Path = CounterPath
	    NumberData.Img04_Frame = GetNumInPos(NumberData.Log4, 1)
	    NumberData.Img04_PosX = NumberData.Img03_PosX + 20
	    NumberData.Img04_PosY = 341

		StringData.Img05_Path = ""
	    NumberData.Img05_Frame = GetNumInPos(NumberData.Log5, 1)
	    NumberData.Img05_PosX = NumberData.Img04_PosX + 20
	    NumberData.Img05_PosY = 341

		--MonSeal counter
		if MonSeal[1] == 0 then
		StringData.Img06_Path = ""
		else
		StringData.Img06_Path = "Quest/Event_2008_07_22_Count_00.bmp"
		end
	    NumberData.Img06_Frame = 0
	    NumberData.Img06_PosX = 257
	    NumberData.Img06_PosY = 343

		if MonSeal[2] == 0 then
		StringData.Img07_Path = ""
		else
		StringData.Img07_Path = "Quest/Event_2008_07_22_Count_00.bmp"
		end
	    NumberData.Img07_Frame = 1
	    NumberData.Img07_PosX = 257 + 12
	    NumberData.Img07_PosY = 343

		if MonSeal[3] == 0 then
		StringData.Img08_Path = ""
		else
		StringData.Img08_Path = "Quest/Event_2008_07_22_Count_00.bmp"
		end
	    NumberData.Img08_Frame = 2
	    NumberData.Img08_PosX = 257 + 12*2
	    NumberData.Img08_PosY = 343

		if MonSeal[4] == 0 then
		StringData.Img09_Path = ""
		else
		StringData.Img09_Path = "Quest/Event_2008_07_22_Count_00.bmp"
		end
	    NumberData.Img09_Frame = 3
	    NumberData.Img09_PosX = 257 + 12 * 3
	    NumberData.Img09_PosY = 343

		if MonSeal[5] == 0 then
		StringData.Img10_Path = ""
		else
		StringData.Img10_Path = "Quest/Event_2008_07_22_Count_00.bmp"
		end
	    NumberData.Img10_Frame = 4
	    NumberData.Img10_PosX = 257 + 12*4
	    NumberData.Img10_PosY = 343

		if MonSeal[6] == 0 then
		StringData.Img11_Path = ""
		else
		StringData.Img11_Path = "Quest/Event_2008_07_22_Count_00.bmp"
		end
	    NumberData.Img11_Frame = 5
	    NumberData.Img11_PosX = 257 + 12*5
	    NumberData.Img11_PosY = 343

		if MonSeal[7] == 0 then
		StringData.Img12_Path = ""
		else
		StringData.Img12_Path = "Quest/Event_2008_07_22_Count_00.bmp"
		end
	    NumberData.Img12_Frame = 6
	    NumberData.Img12_PosX = 257 + 12*6
	    NumberData.Img12_PosY = 343

		if MonSeal[8] == 0 then
		StringData.Img13_Path = ""
		else
		StringData.Img13_Path = "Quest/Event_2008_07_22_Count_00.bmp"
		end
	    NumberData.Img13_Frame = 7
	    NumberData.Img13_PosX = 257 + 12*7
	    NumberData.Img13_PosY = 343

	elseif IsDone() == 2 then
		NumberData.NaviBtn00_Visible = 1
		NumberData.NaviBtn01_Visible = 0

		NumberData.Img_Count = 0

	elseif IsDone() == 3 and Rewarded() == 0 then
		NumberData.NaviBtn00_Visible = 1
		NumberData.NaviBtn01_Visible = 0

		NumberData.Img_Count = 0

	elseif IsDone() == 3 and Rewarded() == 1 then
		NumberData.NaviBtn00_Visible = 1
		NumberData.NaviBtn01_Visible = 0

		NumberData.Img_Count = 0
	end

	return 0
end

function OnNaviButtonClicked()
    OnShowQuest()

    if IsDone() >= 3 -- 보상받은 후
    then

        if NumberData.RelativePageLocation  <= -2
        then
            NumberData.NaviBtn00_Visible = 0
            NumberData.NaviBtn01_Visible = 1
            NumberData.RelativePageLocation = -2

        elseif NumberData.RelativePageLocation == -1
        then
            NumberData.NaviBtn00_Visible = 1
            NumberData.NaviBtn01_Visible = 1

        else
            NumberData.NaviBtn00_Visible = 1
            NumberData.NaviBtn01_Visible = 0
            NumberData.RelativePageLocation = 0
        end

    elseif IsDone() == 2 -- 달성하고 보상받기 전
    then
        if NumberData.RelativePageLocation  <= -1
        then
            NumberData.RelativePageLocation = -1
            NumberData.NaviBtn00_Visible = 0
            NumberData.NaviBtn01_Visible = 1

        else
            NumberData.RelativePageLocation = 0
            NumberData.NaviBtn00_Visible = 1
            NumberData.NaviBtn01_Visible = 0

        end

	elseif IsDone() == 1 then
        NumberData.RelativePageLocation = 0
        NumberData.NaviBtn00_Visible = 0
        NumberData.NaviBtn01_Visible = 0

 	end

	PageNum = IsDone() + NumberData.RelativePageLocation

	StringData.Back_Path = BackPath[PageNum]
	StringData.AniImg00_Path = AniPath[PageNum]
	NumberData.AniImg_Count = 1
	NumberData.AniImg00_Frame = 0
	NumberData.AniImg00_PosX = AniPosX[PageNum]
	NumberData.AniImg00_PosY = AniPosY[PageNum]
	NumberData.AniImg00_Total = 2
	NumberData.AniImg00_Delay = AniDelay[PageNum]

    return 0
end

function CheckDoneButtonVisible()
	if IsDone() == 2 or Rewarded() == 1 then
		return 1
	else
		return 0
	end
end

function IsDone()
	if NumberData.Log2 >= Limit then return 3
	elseif NumberData.Log2 < Limit then
		if NumberData.Log1 >= KillMon and NumberData.Log4 >= KillPen and NumberData.Log5 == KillSeal then return 2
		end
	end
	return 1
end

function Rewarded()
     AfterDay = NumberData.Log3  + (60*60*24)
	-- AfterDay = NumberData.Log3  + (60)

	if NumberData.Log2 >= Limit and CurrentTime > AfterDay then return 1




	end


	return 0
end


function GetNumInPos ( num, pos ) -- pos = 1 or 10 or 100 or else
	numTemp = math.floor (num / pos)
	numInPos = 0
	if numTemp ~= 0
	then
		numInPos = math.mod(numTemp, 10)
	end

	return numInPos
end

function LoadValue ()
	for i= 0, 7 do
		idx= 10^i
		MonSeal[i+1] = GetNumInPos(NumberData.Log5, idx)
	end
end


